CREATE TABLE IF NOT EXISTS utilizadores (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, tipo TEXT NOT NULL DEFAULT 'cliente' CHECK(tipo IN ('cliente','admin')));
CREATE TABLE IF NOT EXISTS restaurantes (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT NOT NULL, localizacao TEXT NOT NULL, preco_medio NUMERIC NOT NULL CHECK(preco_medio >= 0), cozinha TEXT NOT NULL, ativo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS reservas (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, utilizador_id INTEGER NOT NULL REFERENCES utilizadores(id), restaurante_id INTEGER NOT NULL REFERENCES restaurantes(id), data_hora TIMESTAMP NOT NULL, num_pessoas INTEGER NOT NULL CHECK(num_pessoas BETWEEN 1 AND 20));
CREATE TABLE IF NOT EXISTS historico_restaurantes (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, restaurante_id INTEGER NOT NULL REFERENCES restaurantes(id), nome_antigo TEXT NOT NULL, preco_antigo NUMERIC NOT NULL, alterado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
